const theme=document.querySelector('#theme-filter');const priority=document.querySelector('#priority-filter');const epics=[...document.querySelectorAll('.plan-epic')];const stories=[...document.querySelectorAll('.plan-story')];function filter(){let count=0,epicCount=0;epics.forEach(e=>{let visible=0;e.querySelectorAll('.plan-story').forEach(s=>{const show=(theme.value==='all'||e.dataset.theme===theme.value)&&(priority.value==='all'||s.dataset.priority===priority.value);s.hidden=!show;if(show){visible++;count++;}});e.hidden=visible===0;if(visible)epicCount++;});document.querySelector('#backlog-count').textContent=`${count} ${count===1?'story':'stories'} across ${epicCount} ${epicCount===1?'epic':'epics'}`;document.querySelector('#no-stories').hidden=count>0;}theme.addEventListener('change',filter);priority.addEventListener('change',filter);document.querySelector('#clear-filters').addEventListener('click',()=>{theme.value='all';priority.value='all';filter();});document.querySelector('#expand-stories').addEventListener('click',()=>{stories.filter(s=>!s.hidden&&!s.closest('.plan-epic').hidden).forEach(s=>s.open=true);});filter();
